<template><el-dialog v-model="visible" title="建立加工批次" width="min(650px,94vw)" :close-on-click-modal="false" :close-on-press-escape="!busy" :show-close="!busy"><el-form ref="batchForm" :model="form" :rules="rules" scroll-to-error label-width="120px" :disabled="busy"><el-form-item label="工厂"><el-select v-model="factoryId" :disabled="!admin" fit-input-width @change="factoryChanged"><el-option v-for="o in factories" :key="o.id" :label="o.name" :value="o.id"/></el-select></el-form-item><el-form-item label="生产工单" prop="workOrderId" required><el-select v-model="form.workOrderId" fit-input-width @change="orderChanged"><el-option v-for="o in orders" :key="o.id" :label="o.name" :value="o.id"/></el-select></el-form-item><el-form-item label="产品明细" prop="itemId" required><el-select v-model="form.itemId" fit-input-width @change="form.processId=''"> <el-option v-for="(o,i) in items" :key="o.id" :label="o.snapshot.name+' '+(i+1)+'（'+o.quantity+'件）'" :value="o.id"/></el-select></el-form-item><el-form-item label="工序" prop="processId" required><el-select v-model="form.processId" fit-input-width><el-option v-for="o in processes" :key="o.processId" :label="o.processName" :value="o.processId"/></el-select></el-form-item><el-form-item label="加工数量" prop="plannedQuantity" required><el-input v-model="form.plannedQuantity" @input="v=>quantityInput=String(v)" inputmode="numeric"/></el-form-item></el-form><template #footer><el-button :disabled="busy" @click="visible=false">取消</el-button><el-button v-if="actionPermission.has('metal:process-batch:add')" type="primary" :loading="busy" @click="save">确认</el-button></template></el-dialog></template>
<script setup lang="ts">
import type {FormInstance} from 'element-plus'
import {integerError,fieldRule,applyFieldErrors} from '@/utils/input-validation'
import { useActionPermission } from '@/composables/useActionPermission'
const actionPermission=useActionPermission()
import {createUUID} from '@/utils/uuid'
import{ref,reactive,computed,watch,onBeforeUnmount}from'vue';import{ElMessage}from'element-plus';import useUserStore from '@/store/modules/user';import{warehouseOptions,warehouseSave,type Row}from'@/api/metal/warehouse';import{orderDetail}from'@/api/metal/work-order';
const emit=defineEmits(['saved']),visible=ref(false),busy=ref(false),factoryId=ref(''),factories=ref<Row[]>([]),orders=ref<Row[]>([]),items=ref<Row[]>([]),form=reactive<Row>({}),admin=computed(()=>String(useUserStore().id)==='1'),processes=computed(()=>items.value.find(o=>o.id===form.itemId)?.plans??[]);
const batchForm=ref<FormInstance>(),quantityInput=ref<string>()
const choose=(label:string)=>[fieldRule(v=>v?'':'请选择'+label,'change')]
const rules={workOrderId:choose('生产工单'),itemId:choose('产品明细'),processId:choose('工序'),plannedQuantity:[fieldRule(v=>integerError(quantityInput.value??v,'加工数量'),['blur','change'])]}
let epoch=0,dependency=0,disposed=false
async function factoryChanged(){const round=epoch,ticket=++dependency,factory=factoryId.value;form.workOrderId='';form.itemId='';form.processId='';items.value=[];orders.value=[];const r=await warehouseOptions('work-orders',factory);if(!disposed&&round===epoch&&ticket===dependency&&factory===factoryId.value)orders.value=r.data}
async function orderChanged(){const round=epoch,ticket=++dependency,order=form.workOrderId;form.itemId='';form.processId='';items.value=[];const r=await orderDetail(order);if(!disposed&&round===epoch&&ticket===dependency&&order===form.workOrderId)items.value=r.data.items}
async function open(factory?:string){const round=++epoch;Object.assign(form,{requestId:createUUID(),workOrderId:'',itemId:'',processId:'',plannedQuantity:1});quantityInput.value=undefined;batchForm.value?.clearValidate();const r=await warehouseOptions('factories');if(disposed||round!==epoch)return;factories.value=r.data;factoryId.value=factory||(!admin.value?factories.value[0]?.id:'')||'';if(factoryId.value)await factoryChanged();else{orders.value=[];items.value=[]}if(!disposed&&round===epoch)visible.value=true}
async function save(){if(busy.value||!visible.value||!actionPermission.has('metal:process-batch:add'))return;const round=epoch;if(!await batchForm.value?.validate().catch(()=>false)||disposed||round!==epoch||!visible.value||!actionPermission.has('metal:process-batch:add'))return;form.plannedQuantity=Number(form.plannedQuantity);busy.value=true;try{await warehouseSave('process-batch',JSON.parse(JSON.stringify(form)));if(disposed||round!==epoch)return;visible.value=false;ElMessage.success('加工批次已建立');emit('saved')}catch(error){if(!disposed&&round===epoch)applyFieldErrors(batchForm.value,error)}finally{if(!disposed&&round===epoch)busy.value=false}}
watch(visible,value=>{if(!value){epoch++;dependency++;busy.value=false}})
onBeforeUnmount(()=>{disposed=true;epoch++;dependency++})
defineExpose({open})
</script>